.sl-feature-bento {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-feature-bento h2,
.sl-feature-bento h3 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-feature-bento .sl-text-primary { color: var(--smartlearn-primary); }
.sl-feature-bento .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-feature-bento .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-feature-bento .sl-bg-card {
    background-color: var(--smartlearn-card-bg);
    border: 1px solid var(--smartlearn-card-border);
    border-radius: var(--smartlearn-radius, 1rem);
}
.sl-feature-bento .sl-bg-primary { background-color: var(--smartlearn-primary); }
.sl-feature-bento .sl-accent-soft {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
}
.sl-feature-bento .sl-border { border-color: var(--smartlearn-card-border); }
.sl-feature-bento .sl-bento-subtitle { max-width: 700px; }
.sl-feature-bento .sl-bento-lead { max-width: 42ch; }
.sl-feature-bento .sl-icon-badge,
.sl-feature-bento .sl-icon-badge-primary {
    width: 48px;
    height: 48px;
    border-radius: var(--smartlearn-radius, 0.75rem);
}
.sl-feature-bento .sl-icon-badge-primary {
    color: var(--smartlearn-btn-text);
}
.sl-feature-bento .sl-media-container {
    height: 250px;
}
.sl-feature-bento .sl-bento-wide-media {
    min-height: 250px;
}
.sl-feature-bento .sl-media-fallback {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text-muted);
}
.sl-feature-bento .sl-ui-fragment {
    background-color: var(--smartlearn-bg);
    border: 1px solid var(--smartlearn-card-border);
}
.sl-feature-bento .sl-grade-badge {
    background-color: var(--smartlearn-primary);
    color: var(--smartlearn-btn-text);
}
.sl-feature-bento .sl-progress-track {
    height: 6px;
    background-color: color-mix(in srgb, var(--smartlearn-text) 12%, transparent);
}
.sl-feature-bento .sl-progress-fill {
    background-color: var(--smartlearn-primary);
}
.sl-feature-bento .sl-chart-fragment {
    background-color: var(--smartlearn-bg);
    border: 1px solid var(--smartlearn-card-border);
    height: 120px;
}
.sl-feature-bento .sl-bento-item {
    transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), border-color 0.3s ease, box-shadow 0.3s ease;
}
.sl-feature-bento .sl-bento-item:hover {
    transform: translateY(-5px);
    border-color: var(--smartlearn-primary);
    box-shadow: 0 1rem 2.5rem color-mix(in srgb, var(--smartlearn-text) 10%, transparent);
}
.sl-feature-bento .sl-bento-img {
    transition: transform 0.6s ease;
}
.sl-feature-bento .sl-bento-item:hover .sl-bento-img {
    transform: scale(1.05);
}
.sl-feature-bento .sl-glass-panel {
    background-color: var(--smartlearn-card-bg);
    background: color-mix(in srgb, var(--smartlearn-card-bg) 88%, transparent);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid var(--smartlearn-card-border);
}
@media (prefers-reduced-motion: reduce) {
    .sl-feature-bento .sl-bento-item,
    .sl-feature-bento .sl-bento-img {
        transition: none;
    }
    .sl-feature-bento .sl-bento-item:hover,
    .sl-feature-bento .sl-bento-item:hover .sl-bento-img {
        transform: none;
    }
}
